"""Toy Tree-of-Thoughts BFS and LATS MCTS on a stylized arithmetic search.

Task: given integers [4, 6, 4, 1], find an expression using +, -, *, / that
evaluates to 24. This mirrors the Game of 24 benchmark from Yao et al.

ToT is a BFS with a prompted value function. LATS is MCTS over the same
search space with UCT selection.

Stdlib only; no LLM. Value function is symbolic (distance from 24).
"""

from __future__ import annotations

import itertools
import math
import random
from dataclasses import dataclass, field


NUMBERS = [4, 6, 4, 1]
TARGET = 24
OPS = ["+", "-", "*", "/"]


@dataclass
class Node:
    state: tuple[float, ...]
    trace: list[str]
    visits: int = 0
    value_sum: float = 0.0
    children: list["Node"] = field(default_factory=list)

    @property
    def q(self) -> float:
        return self.value_sum / self.visits if self.visits else 0.0


def evaluate(a: float, op: str, b: float) -> float | None:
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        return a / b if b != 0 else None
    return None


def expand(node: Node) -> list[Node]:
    children: list[Node] = []
    state = node.state
    if len(state) < 2:
        return children
    for i, j in itertools.combinations(range(len(state)), 2):
        for op in OPS:
            a, b = state[i], state[j]
            v = evaluate(a, op, b)
            if v is None:
                continue
            remaining = [s for k, s in enumerate(state) if k not in (i, j)]
            new_state = tuple(sorted(remaining + [v], reverse=True))
            step = f"{a}{op}{b}={v}"
            children.append(Node(state=new_state, trace=node.trace + [step]))
    return children


def value(node: Node) -> float:
    if len(node.state) == 1:
        result = node.state[0]
        return 1.0 if abs(result - TARGET) < 1e-6 else -abs(result - TARGET) / 100.0
    best_distance = min(abs(v - TARGET) for v in node.state)
    return -best_distance / 100.0


def tot_bfs(root: Node, max_expansions_per_level: int = 8,
            max_depth: int = 3) -> tuple[Node | None, int]:
    frontier = [root]
    expansions = 0
    for _ in range(max_depth):
        scored: list[tuple[float, Node]] = []
        for node in frontier:
            for child in expand(node):
                expansions += 1
                scored.append((value(child), child))
                if value(child) > 0.99:
                    return child, expansions
        scored.sort(key=lambda p: p[0], reverse=True)
        frontier = [n for _, n in scored[:max_expansions_per_level]]
    best = max(frontier, key=value) if frontier else None
    return best, expansions


def uct(parent: Node, child: Node, c: float = 1.4) -> float:
    if child.visits == 0:
        return float("inf")
    return child.q + c * math.sqrt(math.log(parent.visits) / child.visits)


def select(node: Node) -> Node:
    while node.children:
        node = max(node.children, key=lambda ch: uct(node, ch))
    return node


def simulate(node: Node, depth: int, rng: random.Random) -> float:
    current = node
    for _ in range(depth):
        options = expand(current)
        if not options:
            break
        current = rng.choice(options)
    return value(current)


def backprop(path: list[Node], reward: float) -> None:
    for n in path:
        n.visits += 1
        n.value_sum += reward


def mcts(root: Node, iterations: int, rng: random.Random) -> tuple[Node, int]:
    expansions = 0
    for _ in range(iterations):
        path = [root]
        cur = root
        while cur.children:
            cur = max(cur.children, key=lambda ch: uct(cur, ch))
            path.append(cur)
        if cur.visits > 0 and len(cur.state) > 1:
            cur.children = expand(cur)
            expansions += len(cur.children)
            if cur.children:
                cur = cur.children[0]
                path.append(cur)
        reward = simulate(cur, depth=max(0, 3 - len(cur.trace)), rng=rng)
        backprop(path, reward)
    best_leaf = max(_all_leaves(root), key=value, default=root)
    return best_leaf, expansions


def _all_leaves(node: Node) -> list[Node]:
    if not node.children:
        return [node]
    out: list[Node] = []
    for ch in node.children:
        out.extend(_all_leaves(ch))
    return out


def main() -> None:
    print("=" * 70)
    print("TREE OF THOUGHTS + LATS: Phase 14, Lesson 04")
    print("=" * 70)
    print(f"numbers: {NUMBERS}  target: {TARGET}")

    root_tot = Node(state=tuple(sorted(NUMBERS, reverse=True)), trace=[])
    best_tot, n_tot = tot_bfs(root_tot)
    print("\nToT BFS")
    print("-" * 60)
    if best_tot is not None:
        print(f"  best trace: {best_tot.trace}")
        print(f"  final state: {best_tot.state}  value: {value(best_tot):.3f}")
    print(f"  expansions: {n_tot}")

    rng = random.Random(7)
    root_lats = Node(state=tuple(sorted(NUMBERS, reverse=True)), trace=[])
    root_lats.children = expand(root_lats)
    for ch in root_lats.children:
        ch.visits = 0
    best_lats, n_lats = mcts(root_lats, iterations=80, rng=rng)
    print("\nLATS MCTS")
    print("-" * 60)
    print(f"  best trace: {best_lats.trace}")
    print(f"  final state: {best_lats.state}  value: {value(best_lats):.3f}")
    print(f"  node expansions: {n_lats}")

    print()
    print("Paper headlines (for reference):")
    print("  ToT Game-of-24:  GPT-4 CoT 4%  -> ToT 74%")
    print("  LATS HumanEval:  pass@1 92.7% with GPT-4 (SOTA at paper time)")
    print("  Cost: ToT uses 100-1000x the tokens of CoT. Use with intent.")


if __name__ == "__main__":
    main()

// Lesson: Tree of Thoughts and LATS: Deliberate Search (phase 14 / lesson 04)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/14-agent-engineering/04-tree-of-thoughts-lats/docs/en.md
// Run: npx tsx phases/14-agent-engineering/04-tree-of-thoughts-lats/code/main.ts

export {};

interface Num {
  v: number;
  f: boolean;
}

const NUMBERS = [4, 6, 4, 1];
const TARGET = 24;
const OPS = ["+", "-", "*", "/"];

function pyFloat(x: number): string {
  if (Number.isNaN(x)) return "nan";
  if (!Number.isFinite(x)) return x > 0 ? "inf" : "-inf";
  if (x === 0) return Object.is(x, -0) ? "-0.0" : "0.0";
  const [mant, expStr] = x.toExponential().split("e");
  const exp = parseInt(expStr, 10);
  if (exp < -4 || exp >= 16) {
    const sign = exp < 0 ? "-" : "+";
    return `${mant}e${sign}${String(Math.abs(exp)).padStart(2, "0")}`;
  }
  const s = String(x);
  return s.includes(".") ? s : s + ".0";
}

function numStr(n: Num): string {
  return n.f ? pyFloat(n.v) : String(n.v);
}

function pyFixed(x: number, d: number): string {
  const s = x.toFixed(d);
  return Object.is(x, -0) ? "-" + s : s;
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

class TreeNode {
  visits = 0;
  valueSum = 0;
  children: TreeNode[] = [];

  constructor(public state: Num[], public trace: string[]) {}

  get q(): number {
    return this.visits ? this.valueSum / this.visits : 0;
  }
}

function evaluate(a: Num, op: string, b: Num): Num | null {
  const f = a.f || b.f;
  if (op === "+") return { v: a.v + b.v, f };
  if (op === "-") return { v: a.v - b.v, f };
  if (op === "*") return { v: a.v * b.v, f };
  if (op === "/") return b.v !== 0 ? { v: a.v / b.v, f: true } : null;
  return null;
}

function sortedDesc(xs: Num[]): Num[] {
  return [...xs].sort((p, q) => q.v - p.v);
}

function expand(node: TreeNode): TreeNode[] {
  const children: TreeNode[] = [];
  const state = node.state;
  if (state.length < 2) return children;
  for (let i = 0; i < state.length; i++) {
    for (let j = i + 1; j < state.length; j++) {
      for (const op of OPS) {
        const a = state[i];
        const b = state[j];
        const v = evaluate(a, op, b);
        if (v === null) continue;
        const remaining = state.filter((_s, k) => k !== i && k !== j);
        const newState = sortedDesc([...remaining, v]);
        const step = `${numStr(a)}${op}${numStr(b)}=${numStr(v)}`;
        children.push(new TreeNode(newState, [...node.trace, step]));
      }
    }
  }
  return children;
}

function value(node: TreeNode): number {
  if (node.state.length === 1) {
    const result = node.state[0];
    if (Math.abs(result.v - TARGET) < 1e-6) return 1.0;
    const d = Math.abs(result.v - TARGET);
    return d === 0 && !result.f ? 0 : -d / 100.0;
  }
  let best = node.state[0];
  for (const s of node.state) {
    if (Math.abs(s.v - TARGET) < Math.abs(best.v - TARGET)) best = s;
  }
  const d = Math.abs(best.v - TARGET);
  return d === 0 && !best.f ? 0 : -d / 100.0;
}

function maxBy<T>(xs: T[], key: (x: T) => number): T {
  let best = xs[0];
  let bestK = key(best);
  for (let i = 1; i < xs.length; i++) {
    const k = key(xs[i]);
    if (k > bestK) {
      best = xs[i];
      bestK = k;
    }
  }
  return best;
}

function totBfs(root: TreeNode, maxExpansionsPerLevel = 8, maxDepth = 3): [TreeNode | null, number] {
  let frontier = [root];
  let expansions = 0;
  for (let depth = 0; depth < maxDepth; depth++) {
    const scored: Array<[number, TreeNode]> = [];
    for (const node of frontier) {
      for (const child of expand(node)) {
        expansions += 1;
        scored.push([value(child), child]);
        if (value(child) > 0.99) return [child, expansions];
      }
    }
    scored.sort((p, q) => q[0] - p[0]);
    frontier = scored.slice(0, maxExpansionsPerLevel).map((p) => p[1]);
  }
  const best = frontier.length > 0 ? maxBy(frontier, value) : null;
  return [best, expansions];
}

function uct(parent: TreeNode, child: TreeNode, c = 1.4): number {
  if (child.visits === 0) return Infinity;
  return child.q + c * Math.sqrt(Math.log(parent.visits) / child.visits);
}

function select(node: TreeNode): TreeNode {
  let cur = node;
  while (cur.children.length > 0) {
    const parent = cur;
    cur = maxBy(parent.children, (ch) => uct(parent, ch));
  }
  return cur;
}

function simulate(node: TreeNode, depth: number, rng: () => number): number {
  let current = node;
  for (let d = 0; d < depth; d++) {
    const options = expand(current);
    if (options.length === 0) break;
    current = options[Math.floor(rng() * options.length)];
  }
  return value(current);
}

function backprop(path: TreeNode[], reward: number): void {
  for (const n of path) {
    n.visits += 1;
    n.valueSum += reward;
  }
}

function mcts(root: TreeNode, iterations: number, rng: () => number): [TreeNode, number] {
  let expansions = 0;
  for (let it = 0; it < iterations; it++) {
    const path = [root];
    let cur = root;
    while (cur.children.length > 0) {
      const parent = cur;
      cur = maxBy(parent.children, (ch) => uct(parent, ch));
      path.push(cur);
    }
    if (cur.visits > 0 && cur.state.length > 1) {
      cur.children = expand(cur);
      expansions += cur.children.length;
      if (cur.children.length > 0) {
        cur = cur.children[0];
        path.push(cur);
      }
    }
    const reward = simulate(cur, Math.max(0, 3 - cur.trace.length), rng);
    backprop(path, reward);
  }
  const leaves = allLeaves(root);
  const bestLeaf = leaves.length > 0 ? maxBy(leaves, value) : root;
  return [bestLeaf, expansions];
}

function allLeaves(node: TreeNode): TreeNode[] {
  if (node.children.length === 0) return [node];
  const out: TreeNode[] = [];
  for (const ch of node.children) out.push(...allLeaves(ch));
  return out;
}

function traceRepr(trace: string[]): string {
  return "[" + trace.map((s) => `'${s}'`).join(", ") + "]";
}

function stateRepr(state: Num[]): string {
  if (state.length === 1) return `(${numStr(state[0])},)`;
  return "(" + state.map(numStr).join(", ") + ")";
}

function main(): void {
  console.log("=".repeat(70));
  console.log("TREE OF THOUGHTS + LATS: Phase 14, Lesson 04");
  console.log("=".repeat(70));
  console.log(`numbers: [${NUMBERS.join(", ")}]  target: ${TARGET}`);

  const start = (): Num[] => sortedDesc(NUMBERS.map((v) => ({ v, f: false })));

  const rootTot = new TreeNode(start(), []);
  const [bestTot, nTot] = totBfs(rootTot);
  console.log("\nToT BFS");
  console.log("-".repeat(60));
  if (bestTot !== null) {
    console.log(`  best trace: ${traceRepr(bestTot.trace)}`);
    console.log(`  final state: ${stateRepr(bestTot.state)}  value: ${pyFixed(value(bestTot), 3)}`);
  }
  console.log(`  expansions: ${nTot}`);

  const rng = mulberry32(7);
  const rootLats = new TreeNode(start(), []);
  rootLats.children = expand(rootLats);
  for (const ch of rootLats.children) ch.visits = 0;
  const [bestLats, nLats] = mcts(rootLats, 80, rng);
  console.log("\nLATS MCTS");
  console.log("-".repeat(60));
  console.log(`  best trace: ${traceRepr(bestLats.trace)}`);
  console.log(`  final state: ${stateRepr(bestLats.state)}  value: ${pyFixed(value(bestLats), 3)}`);
  console.log(`  node expansions: ${nLats}`);

  console.log();
  console.log("Paper headlines (for reference):");
  console.log("  ToT Game-of-24:  GPT-4 CoT 4%  -> ToT 74%");
  console.log("  LATS HumanEval:  pass@1 92.7% with GPT-4 (SOTA at paper time)");
  console.log("  Cost: ToT uses 100-1000x the tokens of CoT. Use with intent.");
}

main();
